type EditorKind = "account" | "instrument" | "contract" | "version" | "generate" | "party" | "remittance" | "debt" | "payment" | "reverse" | "qbo";
type EditorState = { kind: EditorKind; payment?: InvestorPayment; instrumentId?: string; contractId?: string } | null;

const tabLabels: Readonly<Record<InvestorTab, string>> = INVESTOR_TAB_LABELS;
/** Exact identity of one QBO line revision. */
function financialSourceReferenceKey(source: FinancialSourceReference): string { return [source.environment, source.realmId, source.objectType, source.objectId, source.lineId ?? "", source.version].join("|"); }
const instrumentKinds: InvestorInstrumentKind[] = ["equity", "preferred_equity", "private_loan", "member_loan"];
const moneyFields = ["principalCents", "interestCents", "returnOfCapitalCents", "distributionCents", "feeCents", "balloonCents", "unclassifiedCents"] as const;

function label(value: string | null | undefined): string { return value ? value.replace(/_/g, " ").replace(/\b\w/g, letter => letter.toUpperCase()) : "—"; }
/** Table dates: "Jun 1" this year, "Jun 1, 2025" otherwise. */
function dateLabel(value: string | null | undefined): string { return formatTableDate(value) ?? "—"; }
/** Field dates: "Sep 24, 2026". */
function longDateLabel(value: string | null | undefined): string { return formatLongDate(value) ?? "—"; }
/** Obligation periods: "Sep 2026". */
function monthLabel(value: string | null | undefined): string { return formatMonthLabel(value) ?? "—"; }
/** One money format across the investor workspace: "$1,234.56", other currencies by ISO code, null as Unknown. */
const money = formatInvestorMoney;
function moneyTotals(values: readonly MoneyValue[]): string {
  const totals = sumMoneyByCurrency(values);
  if (!totals.length) return "—";
  return totals.map(total => total.knownCount === 0 ? `Unknown${total.unknownCount > 1 ? ` (${total.unknownCount})` : ""}` : `${money(total.cents, total.currency)}${total.unknownCount ? ` + ${total.unknownCount} unknown` : ""}`).join(" · ");
}
function cents(value: string, required = false): string | null { const trimmed = value.trim(); if (!trimmed) return required ? null : "0"; if (!/^\d+(?:\.\d{0,2})?$/.test(trimmed)) throw new Error("Enter a non-negative amount with up to two decimals."); const [whole, fraction = ""] = trimmed.split("."); return (BigInt(whole) * BigInt(100) + BigInt(fraction.padEnd(2, "0"))).toString(); }
function monthFor(date = new Date()): string { return `${workspaceToday(date).slice(0, 7)}-01`; }
function shiftMonth(month: string, offset: number): string { const [year, monthNumber] = month.split("-").map(Number); const index = year * 12 + monthNumber - 1 + offset; return `${String(Math.floor(index / 12)).padStart(4, "0")}-${String(index % 12 + 1).padStart(2, "0")}-01`; }
function statusClass(status: string): string { return status === "active" || status === "qbo_posted" || status === "bank_settled" ? "is-positive" : status === "partially_posted" || status === "partially_settled" || status === "manual_recorded" || status === "review_required" ? "is-warning" : status === "archived" || status === "reversed" ? "is-muted" : ""; }
function StatusBadge({ value }: { value: string }) { return <span className={`investors-status ${statusClass(value)}`}>{label(value)}</span>; }
function Loading({ text = "Loading investors…" }: { text?: string }) { return <div className="investors-state" role="status"><LoaderCircle size={17} className="investors-spin" />{text}</div>; }
function ErrorMessage({ error, onRetry }: { error: unknown; onRetry?: () => void }) { if (!error) return null; return <div className="investors-error" role="alert"><CircleAlert size={17} /><span>{error instanceof Error ? error.message : "Investor records could not be loaded."}</span>{onRetry && <button type="button" className="investors-button investors-button-secondary" onClick={onRetry}>Retry</button>}</div>; }
function summaryMoneyTotals(values: readonly MoneyValue[]): string { return values.length ? moneyTotals(values) : "Unknown"; }
function hasPositiveCents(value: string | null | undefined): boolean { return value !== null && value !== undefined && /^-?\d+$/.test(value) && BigInt(value) > BigInt(0); }
function obligationIsOpen(obligation: InvestorDetail["obligations"][number]): boolean {
  if (["bank_settled", "qbo_posted", "manually_recorded", "overpaid", "reversed"].includes(obligation.status)) return false;
  return obligation.remainingDueCents === null || hasPositiveCents(obligation.remainingDueCents);
}
function obligationDueLabel(obligation: InvestorDetail["obligations"][number]): string {
  return obligation.remainingDueCents === null ? `${money(obligation.knownMinimumCents, obligation.currency)} + unknown` : money(obligation.remainingDueCents, obligation.currency);
}
function paymentHistorySort(left: InvestorPayment, right: InvestorPayment): number { return left.paymentOn.localeCompare(right.paymentOn) || left.createdAt.localeCompare(right.createdAt) || String(left.id).localeCompare(String(right.id)); }
function investorDocumentDownloadHref(organizationId: string, documentId: string, legalEntityId: string): string {
  const params = new URLSearchParams({ legalEntityId });
  return `/api/company/${encodeURIComponent(organizationId)}/documents/${encodeURIComponent(documentId)}/download?${params.toString()}`;
}
function Field({ label: fieldLabel, children, wide = false }: { label: string; children: ReactNode; wide?: boolean }) {
  const labelId = `investor-field-${useId().replace(/:/g, "")}`;
  const describedById = `${labelId}-help`;
  const parts = Children.toArray(children);
  type FieldElement = ReactElement<{ className?: string; id?: string; "aria-labelledby"?: string; "aria-describedby"?: string }>;
  const asFieldElement = (part: ReactNode): FieldElement | undefined => isValidElement(part) ? part as FieldElement : undefined;
  const hasHelp = parts.some(part => { const element = asFieldElement(part); return element?.type === "span" && Boolean(element.props.className?.includes("investors-field-note")); });
  let controlAttached = false;
  const labelledChildren = parts.map(part => {
    const element = asFieldElement(part);
    if (!element || controlAttached || (element.type !== "input" && element.type !== "select" && element.type !== "textarea")) return part;
    controlAttached = true;
    return cloneElement(element, { "aria-labelledby": labelId, ...(hasHelp ? { "aria-describedby": describedById } : {}) });
  });
  return <div className={`investors-form-field${wide ? " investors-form-wide" : ""}`}><span id={labelId} className="investors-form-label">{fieldLabel}</span>{labelledChildren.map((part, index) => { const element = asFieldElement(part); return element?.type === "span" && element.props.className?.includes("investors-field-note") ? cloneElement(element, { id: describedById, key: element.key ?? index }) : part; })}</div>;
}

function Dialog({ title, eyebrow, children, onClose, onSubmit, saving, submitLabel = "Save" }: { title: string; eyebrow: string; children: ReactNode; onClose: () => void; onSubmit: (event: FormEvent) => void; saving: boolean; submitLabel?: string }) {
  return <DialogRoot open onOpenChange={open => { if (!open && !saving) onClose(); }}><DialogPrimitive.Portal><DialogPrimitive.Overlay className="investors-dialog-backdrop" /><DialogPrimitive.Content className="investors-dialog" aria-labelledby="investor-dialog-title" aria-busy={saving} onEscapeKeyDown={event => { if (saving) event.preventDefault(); }} onPointerDownOutside={event => { if (saving) event.preventDefault(); }}><header><div><span className="investors-eyebrow">{eyebrow}</span><DialogPrimitive.Title asChild><h2 id="investor-dialog-title">{title}</h2></DialogPrimitive.Title></div><DialogPrimitive.Close asChild><button type="button" className="investors-button investors-button-quiet" aria-label="Close" disabled={saving}><X size={18} /></button></DialogPrimitive.Close></header><form onSubmit={onSubmit}><div className="investors-dialog-body"><fieldset disabled={saving} style={{ border: 0, padding: 0, margin: 0 }}>{children}</fieldset></div><footer className="investors-dialog-footer"><button type="button" className="investors-button investors-button-secondary" onClick={onClose} disabled={saving}>Cancel</button><button type="submit" className="investors-button investors-button-primary" disabled={saving}>{saving ? "Saving…" : submitLabel}</button></footer></form></DialogPrimitive.Content></DialogPrimitive.Portal></DialogRoot>;
}

function AccountEditor({ contacts, onSave, onClose, saving, error }: { contacts: readonly { id: string; displayName: string; kind: string }[]; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const [existing, setExisting] = useState(contacts[0]?.id ?? "");
  const [newContact, setNewContact] = useState(false);
  const [name, setName] = useState("");
  const [contactName, setContactName] = useState("");
  const [contactKind, setContactKind] = useState<"person" | "organization">("person");
  const [notes, setNotes] = useState("");
  const submit = (event: FormEvent) => { event.preventDefault(); if (!name.trim()) return; onSave({ displayName: name.trim(), notes: notes.trim() || null, ...(newContact ? { newContact: { kind: contactKind, displayName: contactName.trim() } } : { contactId: existing }) }); };
  return <Dialog title="New investor" eyebrow="Investor account" onClose={onClose} onSubmit={submit} saving={saving} submitLabel="Create investor"><ErrorMessage error={error} /><div className="investors-form investors-form-grid"><Field label="Account name"><input autoFocus value={name} onChange={event => setName(event.currentTarget.value)} placeholder="Investor or family office" /></Field><Field label="Notes"><input value={notes} onChange={event => setNotes(event.currentTarget.value)} placeholder="Optional" /></Field><div className="investors-form-wide"><label className="investors-checkbox"><input type="checkbox" checked={newContact} onChange={event => setNewContact(event.currentTarget.checked)} />Create a new company contact</label></div>{newContact ? <><Field label="Contact name"><input value={contactName} onChange={event => setContactName(event.currentTarget.value)} placeholder="Legal name" /></Field><Field label="Contact type"><select value={contactKind} onChange={event => setContactKind(event.currentTarget.value as typeof contactKind)}><option value="person">Person</option><option value="organization">Organization</option></select></Field></> : <Field label="Existing contact" wide><select value={existing} onChange={event => setExisting(event.currentTarget.value)}><option value="">Choose a contact</option>{contacts.map(contact => <option key={contact.id} value={contact.id}>{contact.displayName} · {label(contact.kind)}</option>)}</select></Field>}</div></Dialog>;
}

function InstrumentEditor({ detail, entities, onSave, onClose, saving, error }: { detail: InvestorDetail; entities: readonly InvestorWorkspaceEntity[]; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const firstEntity = entities[0]?.id ?? detail.instruments[0]?.legalEntityId ?? "";
  const [name, setName] = useState(""); const [kind, setKind] = useState<InvestorInstrumentKind>("equity"); const [entity, setEntity] = useState(firstEntity); const [currency, setCurrency] = useState(entities.find(item => item.id === firstEntity)?.currency ?? detail.instruments[0]?.currency ?? "USD"); const [committed, setCommitted] = useState(""); const [face, setFace] = useState(""); const [effectiveFrom, setEffectiveFrom] = useState(workspaceToday()); const [maturityOn, setMaturityOn] = useState(""); const [ownership, setOwnership] = useState(""); const [propertyIds, setPropertyIds] = useState<string[]>([]);
  const selectedEntity = entities.find(item => item.id === entity);
  const submit = (event: FormEvent) => { event.preventDefault(); try { onSave({ accountId: detail.id, name: name.trim(), kind, legalEntityId: entity, propertyIds, projectIds: [], currency, committedCents: cents(committed), facePrincipalCents: cents(face), effectiveFrom, maturityOn: maturityOn || null, ownershipBps: ownership.trim() ? percentageToBasisPoints(ownership) : null, notes: null }); } catch (submitError) { onSave({ __validationError: submitError instanceof Error ? submitError.message : "Enter valid values." }); } };
  return <Dialog title="New investment" eyebrow="Ownership or instrument" onClose={onClose} onSubmit={submit} saving={saving} submitLabel="Create investment"><ErrorMessage error={error} /><div className="investors-form investors-form-grid"><Field label="Name" wide><input autoFocus value={name} onChange={event => setName(event.currentTarget.value)} placeholder="Preferred equity, member loan…" /></Field><Field label="Type"><select value={kind} onChange={event => setKind(event.currentTarget.value as InvestorInstrumentKind)}>{instrumentKinds.map(value => <option key={value} value={value}>{label(value)}</option>)}</select></Field><Field label="Currency"><input value={currency} onChange={event => setCurrency(event.currentTarget.value.toUpperCase())} maxLength={3} /></Field><Field label="Legal entity"><select value={entity} onChange={event => { setEntity(event.currentTarget.value); setCurrency(entities.find(item => item.id === event.currentTarget.value)?.currency ?? currency); }}><option value="">Choose entity</option>{entities.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Committed amount"><input inputMode="decimal" value={committed} onChange={event => setCommitted(event.currentTarget.value)} placeholder="0.00" /></Field><Field label="Principal face value"><input inputMode="decimal" value={face} onChange={event => setFace(event.currentTarget.value)} placeholder="0.00" /></Field><Field label="Effective from"><input type="date" value={effectiveFrom} onChange={event => setEffectiveFrom(event.currentTarget.value)} /></Field><Field label="Maturity (optional)"><input type="date" value={maturityOn} onChange={event => setMaturityOn(event.currentTarget.value)} /></Field><Field label="Ownership %"><input inputMode="decimal" value={ownership} onChange={event => setOwnership(event.currentTarget.value)} placeholder="25.00" /><span className="investors-field-note">Enter a percentage; it is saved exactly to basis points.</span></Field>{selectedEntity && <div className="investors-form-wide"><span className="investors-eyebrow">Properties</span><div className="investors-checkbox-grid">{selectedEntity.properties.map(property => <label className="investors-checkbox" key={property.id}><input type="checkbox" checked={propertyIds.includes(property.id)} onChange={event => setPropertyIds(current => event.currentTarget.checked ? [...current, property.id] : current.filter(id => id !== property.id))} />{property.name}</label>)}</div></div>}</div></Dialog>;
}

function TermsFields({ onChange, values }: { values: Record<string, string | boolean | null>; onChange: (key: string, value: string | boolean | null) => void }) {
  const amountField = (key: string, fieldLabel: string) => <Field label={fieldLabel}><input inputMode="decimal" value={String(values[key] ?? "")} onChange={event => onChange(key, event.currentTarget.value || null)} placeholder="0.00" /></Field>;
  return <div className="investors-form-sections">
    <details className="investors-form-section" open>
      <summary>Schedule</summary>
      <div className="investors-form investors-form-grid">
        <Field label="Schedule"><select value={String(values.schedule ?? "monthly")} onChange={event => onChange("schedule", event.currentTarget.value)}><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option><option value="annual">Annual</option><option value="at_maturity">At maturity</option><option value="custom">Custom (generation unavailable)</option></select></Field>
        <Field label="Payment day"><input type="number" min="1" max="31" value={String(values.paymentDay ?? "31")} onChange={event => onChange("paymentDay", event.currentTarget.value)} /></Field>
        <Field label="Month-end rule"><select value={String(values.monthEndRule ?? "calendar_day_or_month_end")} onChange={event => onChange("monthEndRule", event.currentTarget.value)}><option value="calendar_day_or_month_end">Calendar day or month end</option><option value="month_end">Month end</option></select></Field>
      </div>
    </details>
    <details className="investors-form-section" open>
      <summary>Recurring payments</summary>
      <div className="investors-form investors-form-grid">
        <Field label="Annual rate %"><input inputMode="decimal" value={String(values.annualRate ?? "")} onChange={event => onChange("annualRate", event.currentTarget.value || null)} placeholder="12.00" /><span className="investors-field-note">Enter a percentage; for example, 12.00 means 12%.</span></Field>
        {amountField("fixedPayment", "Fixed payment")}
        {amountField("principalPayment", "Principal payment")}
        {amountField("interestPayment", "Interest payment")}
        {amountField("returnOfCapital", "Return of capital")}
        {amountField("distribution", "Distribution")}
      </div>
    </details>
    <details className="investors-form-section">
      <summary>Third-party and maturity terms</summary>
      <div className="investors-form investors-form-grid">
        {amountField("investorSpread", "Investor spread")}
        {amountField("thirdPartyInstallment", "Third-party installment")}
        {amountField("balloon", "Balloon")}
        {amountField("originalPrincipal", "Original principal")}
        {amountField("maturityTotal", "Maturity total")}
        {amountField("fixedProfit", "Fixed maturity profit")}
        <Field label="Maturity payoff (unknown until evidence)" wide><input inputMode="decimal" value={String(values.maturityPayoff ?? "")} onChange={event => onChange("maturityPayoff", event.currentTarget.value || null)} placeholder="0.00" /></Field>
      </div>
    </details>
    <details className="investors-form-section">
      <summary>Calculation rules</summary>
      <div className="investors-form investors-form-grid">
        <Field label="Day count"><select value={String(values.dayCount ?? "actual_365")} onChange={event => onChange("dayCount", event.currentTarget.value)}><option value="actual_365">Actual / 365</option><option value="actual_360">Actual / 360</option><option value="30_360">30 / 360</option></select></Field>
        <label className="investors-checkbox"><input type="checkbox" checked={Boolean(values.interestOnly)} onChange={event => onChange("interestOnly", event.currentTarget.checked)} />Interest only</label>
      </div>
    </details>
  </div>;
}

function ContractEditor({ detail, instrumentId, documents: sourceDocuments, onInstrumentChange, onSave, onClose, saving, error, contract }: { detail: InvestorDetail; instrumentId: string; documents: readonly InvestorDocumentOption[]; onInstrumentChange: (instrumentId: string) => void; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown; contract?: InvestorContract }) {
  const documents = sourceDocuments.filter(document => !document.id.startsWith("company-document:") || ["contract", "loan", "investor_agreement"].includes(document.type));
  const [title, setTitle] = useState(""); const [kind, setKind] = useState("investment_agreement"); const [status, setStatus] = useState("draft"); const [effectiveFrom, setEffectiveFrom] = useState(workspaceToday()); const [signedOn, setSignedOn] = useState(""); const [docs, setDocs] = useState<string[]>([]); const [terms, setTerms] = useState<Record<string, string | boolean | null>>({ schedule: "monthly", paymentDay: "31", monthEndRule: "calendar_day_or_month_end", dayCount: "actual_365", interestOnly: false });
  const updateTerm = (key: string, value: string | boolean | null) => setTerms(current => ({ ...current, [key]: value }));
  const amount = (key: string) => terms[key] ? cents(String(terms[key])) : null;
  const submit = (event: FormEvent) => { event.preventDefault(); try { const normalized = { schedule: terms.schedule, paymentDay: Number(terms.paymentDay ?? 31), monthEndRule: terms.monthEndRule, annualRate: terms.annualRate ? percentageToRateDecimal(String(terms.annualRate)) : null, preferredReturnRate: null, returnMultiple: null, fixedPaymentCents: amount("fixedPayment"), principalPaymentCents: amount("principalPayment"), interestPaymentCents: amount("interestPayment"), returnOfCapitalCents: amount("returnOfCapital"), distributionCents: amount("distribution"), balloonCents: amount("balloon"), originalPrincipalCents: amount("originalPrincipal"), maturityTotalCents: amount("maturityTotal"), fixedProfitCents: amount("fixedProfit"), maturityPayoffCents: amount("maturityPayoff"), thirdPartyInstallmentCents: amount("thirdPartyInstallment"), investorSpreadCents: amount("investorSpread"), unknownComponentKinds: amount("thirdPartyInstallment") ? ["principal", "interest"] : [], interestOnly: Boolean(terms.interestOnly), dayCount: terms.dayCount }; onSave(contract ? { contractId: contract.id, status, effectiveFrom, signedOn: signedOn || null, terms: normalized, sourceDocumentIds: docs } : { instrumentId, title: title.trim(), kind, status, effectiveFrom, signedOn: signedOn || null, terms: normalized, sourceDocumentIds: docs }); } catch (submitError) { onSave({ __validationError: submitError instanceof Error ? submitError.message : "Enter valid values." }); } };
  return <Dialog title={contract ? "New version" : "New contract"} eyebrow={contract ? contract.title : "Versioned agreement"} onClose={onClose} onSubmit={submit} saving={saving} submitLabel={contract ? "Create version" : "Create contract"}><ErrorMessage error={error} /><div className="investors-form investors-form-grid">{!contract && <Field label="Instrument"><select value={instrumentId} onChange={event => { onInstrumentChange(event.currentTarget.value); setDocs([]); }}>{detail.instruments.map(item => <option key={item.id} value={item.id}>{item.name} · {label(item.kind)}</option>)}</select></Field>}<Field label="Status"><select value={status} onChange={event => setStatus(event.currentTarget.value)}><option value="draft">Draft</option><option value="in_review">In review</option><option value="active">Active</option></select></Field>{!contract && <><Field label="Title" wide><input autoFocus value={title} onChange={event => setTitle(event.currentTarget.value)} placeholder="Promissory note or investment agreement" /></Field><Field label="Contract kind"><select value={kind} onChange={event => setKind(event.currentTarget.value)}><option value="investment_agreement">Investment agreement</option><option value="promissory_note">Promissory note</option><option value="operating_agreement">Operating agreement</option><option value="amendment">Amendment</option><option value="distribution_policy">Distribution policy</option><option value="other">Other</option></select></Field></>}<Field label="Effective from"><input type="date" value={effectiveFrom} onChange={event => setEffectiveFrom(event.currentTarget.value)} /></Field><Field label="Signed on"><input type="date" value={signedOn} onChange={event => setSignedOn(event.currentTarget.value)} /></Field><div className="investors-form-wide"><span className="investors-form-label">Source documents</span>{documents.length ? <div className="investors-checkbox-grid">{documents.map(document => <label className="investors-checkbox" key={document.id}><input type="checkbox" checked={docs.includes(document.id)} onChange={event => setDocs(current => event.currentTarget.checked ? [...current, document.id] : current.filter(id => id !== document.id))} /> <FileText size={14} />{document.fileName} · {label(document.state)}</label>)}</div> : <p className="investors-note">No authorized files were found for this instrument's properties.</p>}</div><div className="investors-form-wide"><span className="investors-eyebrow">Payment terms</span><TermsFields values={terms} onChange={updateTerm} /></div></div></Dialog>;
}

function GenerateEditor({ detail, contractId, onSave, onClose, saving, error }: { detail: InvestorDetail; contractId: string; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const contract = detail.contracts.find(item => String(item.id) === contractId);
  const [fromMonth, setFromMonth] = useState(monthFor().slice(0, 7));
  const [throughMonth, setThroughMonth] = useState(shiftMonth(monthFor(), 11).slice(0, 7));
  const submit = (event: FormEvent) => { event.preventDefault(); if (!contract) return; if (!/^\d{4}-\d{2}$/.test(fromMonth) || !/^\d{4}-\d{2}$/.test(throughMonth) || throughMonth < fromMonth) { onSave({ __validationError: "Choose a month range." }); return; } onSave({ instrumentId: contract.instrumentId, contractId: contract.id, fromMonth: `${fromMonth}-01`, throughMonth: `${throughMonth}-01` }); };
  return <Dialog title="Generate obligations" eyebrow={contract?.title ?? "Agreement"} onClose={onClose} onSubmit={submit} saving={saving} submitLabel="Generate"><ErrorMessage error={error} /><div className="investors-form investors-form-grid"><Field label="From month"><input type="month" value={fromMonth} onChange={event => setFromMonth(event.currentTarget.value)} /></Field><Field label="Through month"><input type="month" value={throughMonth} onChange={event => setThroughMonth(event.currentTarget.value)} /></Field></div></Dialog>;
}

function PartyEditor({ detail, realms, documents, onSave, onClose, saving, error }: { detail: InvestorDetail; realms: readonly { legalEntityId: string; environment: string; realmId: string }[]; documents: readonly { id: string; fileName: string; state: string }[]; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const [realmKey, setRealmKey] = useState(realms[0] ? `${realms[0].legalEntityId}|${realms[0].environment}|${realms[0].realmId}` : "");
  const [partyKind, setPartyKind] = useState("investor"); const [payeeType, setPayeeType] = useState("Vendor"); const [payeeId, setPayeeId] = useState(""); const [displayName, setDisplayName] = useState(detail.displayName); const [effectiveFrom, setEffectiveFrom] = useState(workspaceToday()); const [documentId, setDocumentId] = useState("");
  useEffect(() => {
    if (realmKey || !realms[0]) return;
    setRealmKey(`${realms[0].legalEntityId}|${realms[0].environment}|${realms[0].realmId}`);
  }, [realmKey, realms]);
  const submit = (event: FormEvent) => { event.preventDefault(); const [legalEntityId, environment, realmId] = realmKey.split("|"); if (!legalEntityId || !payeeId.trim() || !displayName.trim()) { onSave({ __validationError: "Choose the QBO company and enter the payee." }); return; } onSave({ accountId: detail.id, providerParty: { provider: "qbo", organizationId: detail.organizationId, legalEntityId, environment, realmId, objectType: payeeType, objectId: payeeId.trim() }, partyKind, contactId: detail.contactId, displayName: displayName.trim(), sourceDocumentId: documentId || null, effectiveFrom, effectiveTo: null }); };
  return <Dialog title="New party mapping" eyebrow="QuickBooks payee" onClose={onClose} onSubmit={submit} saving={saving} submitLabel="Save mapping"><ErrorMessage error={error} /><div className="investors-form investors-form-grid"><Field label="QBO company" wide><select value={realmKey} onChange={event => setRealmKey(event.currentTarget.value)} disabled={!realms.length}>{realms.length ? realms.map(item => <option key={`${item.legalEntityId}|${item.environment}|${item.realmId}`} value={`${item.legalEntityId}|${item.environment}|${item.realmId}`}>{item.realmId} · {label(item.environment)}</option>) : <option value="">No mirrored QBO company</option>}</select></Field><Field label="Party"><select value={partyKind} onChange={event => setPartyKind(event.currentTarget.value)}><option value="investor">Investor</option><option value="third_party_lender">Third-party lender</option></select></Field><Field label="Payee type"><select value={payeeType} onChange={event => setPayeeType(event.currentTarget.value)}><option value="Vendor">Vendor</option><option value="Customer">Customer</option><option value="Employee">Employee</option></select></Field><Field label="QBO payee ID"><input value={payeeId} onChange={event => setPayeeId(event.currentTarget.value)} /></Field><Field label="Display name"><input value={displayName} onChange={event => setDisplayName(event.currentTarget.value)} /></Field><Field label="Effective from"><input type="date" value={effectiveFrom} onChange={event => setEffectiveFrom(event.currentTarget.value)} /></Field><Field label={partyKind === "third_party_lender" ? "Written authority" : "Document (optional)"} wide><select value={documentId} onChange={event => setDocumentId(event.currentTarget.value)}><option value="">None</option>{documents.map(document => <option key={document.id} value={document.id}>{document.fileName}</option>)}</select></Field></div></Dialog>;
}

function RemittanceEditor({ detail, documents, onSave, onClose, saving, error }: { detail: InvestorDetail; documents: readonly { id: string; fileName: string; state: string }[]; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const mappings = detail.partyMappings.filter(item => item.status === "active");
  const [instrumentId, setInstrumentId] = useState(String(detail.instruments[0]?.id ?? "")); const [partyMappingId, setPartyMappingId] = useState(String(mappings[0]?.id ?? "")); const [documentId, setDocumentId] = useState(""); const [effectiveFrom, setEffectiveFrom] = useState(workspaceToday()); const [notes, setNotes] = useState("");
  const contracts = detail.contracts.filter(item => String(item.instrumentId) === instrumentId); const [contractId, setContractId] = useState("");
  const submit = (event: FormEvent) => { event.preventDefault(); if (!instrumentId || !partyMappingId || !documentId) { onSave({ __validationError: "Choose the instrument, payee and written instruction." }); return; } onSave({ accountId: detail.id, instrumentId, contractId: contractId || null, partyMappingId, sourceDocumentId: documentId, effectiveFrom, effectiveTo: null, notes: notes.trim() || null }); };
  return <Dialog title="New remittance instruction" eyebrow="Where payments go" onClose={onClose} onSubmit={submit} saving={saving} submitLabel="Save instruction"><ErrorMessage error={error} /><div className="investors-form investors-form-grid"><Field label="Instrument"><select value={instrumentId} onChange={event => { setInstrumentId(event.currentTarget.value); setContractId(""); }}>{detail.instruments.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="Agreement"><select value={contractId} onChange={event => setContractId(event.currentTarget.value)}><option value="">Any</option>{contracts.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select></Field><Field label="Pay to"><select value={partyMappingId} onChange={event => setPartyMappingId(event.currentTarget.value)} disabled={!mappings.length}>{mappings.length ? mappings.map(item => <option key={item.id} value={item.id}>{item.displayName} · {label(item.partyKind)}</option>) : <option value="">Add a party mapping first</option>}</select></Field><Field label="Effective from"><input type="date" value={effectiveFrom} onChange={event => setEffectiveFrom(event.currentTarget.value)} /></Field><Field label="Written instruction" wide><select value={documentId} onChange={event => setDocumentId(event.currentTarget.value)}><option value="">Choose document</option>{documents.map(document => <option key={document.id} value={document.id}>{document.fileName}</option>)}</select></Field><Field label="Notes" wide><input value={notes} onChange={event => setNotes(event.currentTarget.value)} /></Field></div></Dialog>;
}

function DebtEditor({ detail, onSave, onClose, saving, error }: { detail: InvestorDetail; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const debtInstrument = detail.instruments.find(item => item.kind === "private_loan" || item.kind === "member_loan"); const [instrumentId, setInstrumentId] = useState(String(debtInstrument?.id ?? "")); const selected = detail.instruments.find(item => String(item.id) === instrumentId); const [principal, setPrincipal] = useState(""); const [funded, setFunded] = useState(""); const [outstanding, setOutstanding] = useState(""); const [rate, setRate] = useState("0"); const [day, setDay] = useState("31"); const [schedule, setSchedule] = useState("monthly"); const [dayCount, setDayCount] = useState("actual_365"); const [firstDue, setFirstDue] = useState(monthFor()); const submit = (event: FormEvent) => { event.preventDefault(); try { onSave({ instrumentId, legalEntityId: selected?.legalEntityId, debtKind: selected?.kind, currency: selected?.currency, originalPrincipalCents: cents(principal), fundedCapitalCents: cents(funded, true), outstandingPrincipalCents: cents(outstanding, true), annualRate: percentageToRateDecimal(rate), schedule, paymentDay: Number(day), monthEndRule: "calendar_day_or_month_end", firstDueMonth: firstDue, interestOnlyUntil: null, maturityOn: selected?.maturityOn ?? null, amortizationMonths: null, balloonCents: null, dayCount }); } catch (submitError) { onSave({ __validationError: submitError instanceof Error ? submitError.message : "Enter valid values." }); } };
  return <Dialog title="New debt schedule" eyebrow="Investor debt" onClose={onClose} onSubmit={submit} saving={saving} submitLabel="Create debt"><ErrorMessage error={error} /><div className="investors-form investors-form-grid"><Field label="Loan instrument" wide><select value={instrumentId} onChange={event => setInstrumentId(event.currentTarget.value)}>{detail.instruments.filter(item => item.kind === "private_loan" || item.kind === "member_loan").map(item => <option key={item.id} value={item.id}>{item.name} · {item.currency}</option>)}</select></Field><Field label="Original principal"><input inputMode="decimal" value={principal} onChange={event => setPrincipal(event.currentTarget.value)} /></Field><Field label="Funded capital"><input inputMode="decimal" value={funded} onChange={event => setFunded(event.currentTarget.value)} /></Field><Field label="Outstanding principal"><input inputMode="decimal" value={outstanding} onChange={event => setOutstanding(event.currentTarget.value)} /></Field><Field label="Annual rate %"><input inputMode="decimal" value={rate} onChange={event => setRate(event.currentTarget.value)} placeholder="12.00" /><span className="investors-field-note">Enter a percentage; for example, 12.00 means 12%.</span></Field><Field label="Schedule"><select value={schedule} onChange={event => setSchedule(event.currentTarget.value)}><option value="monthly">Monthly</option><option value="quarterly">Quarterly</option><option value="annual">Annual</option><option value="at_maturity">At maturity</option></select></Field><Field label="Payment day"><input type="number" min="1" max="31" value={day} onChange={event => setDay(event.currentTarget.value)} /></Field><Field label="First due month"><input type="month" value={firstDue.slice(0, 7)} onChange={event => setFirstDue(`${event.currentTarget.value}-01`)} /></Field><Field label="Day count"><select value={dayCount} onChange={event => setDayCount(event.currentTarget.value)}><option value="actual_365">Actual / 365</option><option value="actual_360">Actual / 360</option><option value="30_360">30 / 360</option></select></Field></div></Dialog>;
}

function displayCents(value: string | null | undefined): string {
  const amount = BigInt(value ?? "0");
  const negative = amount < BigInt(0);
  const absolute = (negative ? -amount : amount).toString().padStart(3, "0");
  return `${negative ? "-" : ""}${absolute.slice(0, -2)}.${absolute.slice(-2)}`;
}

function PaymentEditor({ detail, payment, onSave, onClose, saving, error }: { detail: InvestorDetail; payment?: InvestorPayment; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const [instrumentId, setInstrumentId] = useState(() => String(payment?.instrumentId ?? detail.instruments[0]?.id ?? ""));
  const selected = detail.instruments.find(item => String(item.id) === instrumentId);
  const [obligationId, setObligationId] = useState(() => String(payment?.obligationId ?? ""));
  const [kind, setKind] = useState<string>(() => payment?.kind === "correction" ? "distribution" : payment?.kind ?? "distribution");
  const [paymentOn, setPaymentOn] = useState(() => payment?.paymentOn.slice(0, 10) ?? workspaceToday());
  const [method, setMethod] = useState<string>(() => payment?.method === "qbo" ? "manual" : payment?.method ?? "manual");
  const [currency, setCurrency] = useState(() => payment?.currency ?? selected?.currency ?? "USD");
  const [values, setValues] = useState<Record<string, string>>(() => Object.fromEntries(moneyFields.map(field => [field, payment ? displayCents(payment.amounts[field]) : ""])));
  const obligations = detail.obligations.filter(item => String(item.instrumentId) === instrumentId && item.status !== "bank_settled" && item.status !== "reversed");
  const updateInstrument = (value: string) => { setInstrumentId(value); const item = detail.instruments.find(candidate => String(candidate.id) === value); setCurrency(item?.currency ?? "USD"); if (!payment) setObligationId(""); };
  const submit = (event: FormEvent) => {
    event.preventDefault();
    try {
      const amounts = Object.fromEntries(moneyFields.map(field => [field, cents(values[field] ?? "")])) as Record<string, string>;
      const obligation = obligationId ? detail.obligations.find(item => String(item.id) === obligationId) : undefined;
      if (payment) {
        onSave({ paymentId: payment.id, obligationId: obligationId || null, contractId: obligation?.contractId ?? payment.contractId, kind, method, paymentOn, periodMonth: obligation?.periodMonth ?? payment.periodMonth, amounts, reason: "Manual correction requested from investor activity" });
      } else {
        onSave({ accountId: detail.id, instrumentId, contractId: obligation?.contractId ?? null, obligationId: obligationId || null, kind, method, paymentOn, periodMonth: obligation?.periodMonth ?? null, currency, amounts });
      }
    } catch (submitError) { onSave({ __validationError: submitError instanceof Error ? submitError.message : "Enter valid values." }); }
  };
  return <Dialog title={payment ? "Edit manual payment" : "Record payment"} eyebrow="Monthly payment log" onClose={onClose} onSubmit={submit} saving={saving} submitLabel={payment ? "Save correction" : "Record manually"}><ErrorMessage error={error} /><p className="investors-note">Manual entries stay awaiting verification until a verified QBO posting is linked. Bank settlement is read from linked evidence when available.</p><div className="investors-form investors-form-grid"><Field label="Instrument" wide><select name="instrumentId" value={instrumentId} onChange={event => updateInstrument(event.currentTarget.value)}>{detail.instruments.map(item => <option key={item.id} value={item.id}>{item.name} · {item.currency}</option>)}</select></Field><Field label="Obligation (optional)" wide><select name="obligationId" value={obligationId} onChange={event => setObligationId(event.currentTarget.value)}><option value="">Unapplied account activity</option>{obligations.map(item => <option key={item.id} value={item.id}>{monthLabel(item.periodMonth)} · due {obligationExpectedLabel(item)} · {label(item.status)}</option>)}</select></Field><Field label="Payment kind"><select name="kind" value={kind} onChange={event => setKind(event.currentTarget.value)}><option value="contribution">Contribution</option><option value="return_of_capital">Return of capital</option><option value="distribution">Distribution</option><option value="principal">Principal</option><option value="interest">Interest</option><option value="fee">Fee</option><option value="balloon">Balloon</option></select></Field><Field label="Method"><select name="method" value={method} onChange={event => setMethod(event.currentTarget.value)}><option value="manual">Manual</option><option value="ach">ACH</option><option value="wire">Wire</option><option value="check">Check</option></select></Field><Field label="Payment date"><input name="paymentOn" type="date" value={paymentOn} onChange={event => setPaymentOn(event.currentTarget.value)} /></Field><Field label="Currency"><input name="currency" value={currency} onChange={event => setCurrency(event.currentTarget.value.toUpperCase())} maxLength={3} /></Field>{moneyFields.map(field => <Field key={field} label={label(field.replace("Cents", ""))}><input name={field} inputMode="decimal" value={values[field]} onChange={event => setValues(current => ({ ...current, [field]: event.currentTarget.value }))} placeholder="0.00" /></Field>)}</div></Dialog>;
}

function ReverseEditor({ payment, onSave, onClose, saving, error }: { payment: InvestorPayment; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const [reason, setReason] = useState("Manual correction requested from investor activity");
  const [paymentOn, setPaymentOn] = useState(workspaceToday());
  const submit = (event: FormEvent) => { event.preventDefault(); if (!reason.trim()) { onSave({ __validationError: "Enter a reason for the reversal." }); return; } onSave({ paymentId: payment.id, reason: reason.trim(), paymentOn }); };
  return <Dialog title="Reverse payment" eyebrow="Append-only correction" onClose={onClose} onSubmit={submit} saving={saving} submitLabel="Reverse payment"><ErrorMessage error={error} /><p className="investors-note">The original activity stays in the audit history. A linked reversal offsets its amounts and allocations.</p><div className="investors-form investors-form-grid"><Field label="Reason" wide><textarea name="reason" value={reason} onChange={event => setReason(event.currentTarget.value)} rows={3} /></Field><Field label="Reversal date"><input name="paymentOn" type="date" value={paymentOn} onChange={event => setPaymentOn(event.currentTarget.value)} /></Field></div></Dialog>;
}

function SourceEditor({ payment, sources, sourcesLoading, onSave, onClose, saving, error }: { payment: InvestorPayment; sources: readonly FinancialSourceLineResolution[]; sourcesLoading: boolean; onSave: (payload: Record<string, unknown>) => void; onClose: () => void; saving: boolean; error: unknown }) {
  const [selectedSourceKey, setSelectedSourceKey] = useState("");
  const sourceOptions = useMemo(() => sources.filter(source => {
    if (source.currency !== payment.currency || BigInt(source.amountCents) < BigInt(payment.amountCents) || source.postingState !== "posted") return false;
    if (payment.kind === "contribution") return source.transactionType === "Deposit" && source.flow === "incoming" && source.lineRole === "receipt";
    return source.flow === "outgoing" && ((source.transactionType === "BillPayment" && source.lineRole === "payment_source" && source.direction === "credit") || (source.transactionType === "Purchase" && source.lineRole === "expense" && source.direction === "debit"));
  }), [payment.amountCents, payment.currency, payment.kind, sources]);
  const selectedSource = sourceOptions.find(source => financialSourceReferenceKey(source.source) === selectedSourceKey);
  useEffect(() => { if (selectedSourceKey && sourceOptions.some(source => financialSourceReferenceKey(source.source) === selectedSourceKey)) return; setSelectedSourceKey(sourceOptions[0] ? financialSourceReferenceKey(sourceOptions[0].source) : ""); }, [selectedSourceKey, sourceOptions]);
  const sourceLabel = (source: FinancialSourceLineResolution): string => {
    const date = source.postedOn ? longDateLabel(source.postedOn) : "Posted date unavailable";
    const detail = source.description?.trim() || label(source.transactionType);
    return `${date} · ${detail} · ${money(source.amountCents, source.currency)}`;
  };
  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!selectedSource) { onSave({ __validationError: sourcesLoading ? "Loading current QBO source lines…" : "Choose a current posted QBO source line." }); return; }
    onSave({ paymentId: payment.id, source: { provider: "qbo", reference: selectedSource.source, currency: selectedSource.currency, amountCents: payment.amountCents } });
  };
  return <Dialog title="Link QBO posting" eyebrow="Verified source evidence" onClose={onClose} onSubmit={submit} saving={saving} submitLabel="Verify QBO"><ErrorMessage error={error} /><div className="investors-form investors-form-grid"><Field label="Posted QBO transaction" wide><select value={selectedSourceKey} onChange={event => setSelectedSourceKey(event.currentTarget.value)} disabled={sourcesLoading || !sourceOptions.length}><option value="">{sourcesLoading ? "Loading source lines…" : sourceOptions.length ? "Choose a source line" : "No matching source lines"}</option>{sourceOptions.map(source => <option key={financialSourceReferenceKey(source.source)} value={financialSourceReferenceKey(source.source)}>{sourceLabel(source)}</option>)}</select></Field><p className="investors-note investors-form-wide">Choose the scoped posted transaction that covers this {payment.kind === "contribution" ? "contribution" : "payment"}. The recorded amount is checked against the selected line.</p></div></Dialog>;
}

function SummaryMetric({ name, value, detail }: { name: string; value: string; detail?: string }) {
  return <div className="investors-summary-metric"><span>{name}</span><strong>{value}</strong>{detail && <small>{detail}</small>}</div>;
}

function InvestorSummary({ account }: { account: InvestorDetail }) {
  const rollups = account.rollups;
  const committed = summaryMoneyTotals(rollups.map(rollup => ({ cents: rollup.committedCents, currency: rollup.currency })));
  const funded = summaryMoneyTotals(rollups.map(rollup => ({ cents: rollup.fundedCents, currency: rollup.currency })));
  const returned = summaryMoneyTotals(rollups.map(rollup => ({ cents: rollup.returnedCents, currency: rollup.currency })));
  const remainingCapital = summaryMoneyTotals(rollups.map(rollup => ({ cents: rollup.remainingContributedCents, currency: rollup.currency })));
  const debtRecords = account.debt;
  const remainingPrincipal = summaryMoneyTotals(debtRecords.map(debt => ({ cents: debt.outstandingPrincipalCents, currency: debt.currency })));
  const openObligations = account.obligations.filter(obligationIsOpen).sort((left, right) => left.dueOn.localeCompare(right.dueOn) || String(left.id).localeCompare(String(right.id)));
  const openObligationAmount = openObligations.length ? moneyTotals(openObligations.map(item => ({ cents: item.remainingDueCents ?? item.knownMinimumCents, currency: item.currency }))) : account.obligations.length ? "No open amount" : "Unknown";
  const next = openObligations[0];
  const nextValue = next ? obligationDueLabel(next) : account.obligations.length ? "No open payment" : "Unknown";
  const nextDetail = next ? `${dateLabel(next.dueOn)} · ${label(next.status)}` : account.obligations.length ? "All loaded obligations are closed" : "No obligation data loaded";
  const maturities = account.instruments.map(instrument => {
    const debt = debtRecords.find(candidate => String(candidate.instrumentId) === String(instrument.id));
    return { instrument, maturityOn: debt?.maturityOn ?? instrument.maturityOn, balloonCents: debt?.balloonCents ?? null };
  }).filter(item => item.maturityOn !== null).sort((left, right) => left.maturityOn!.localeCompare(right.maturityOn!));
  const maturity = maturities[0];
  return <div className="investors-summary" aria-label="Investor position summary">
    <SummaryMetric name="Committed" value={committed} />
    <SummaryMetric name="Verified funded" value={funded} detail="QBO or bank evidence" />
    <SummaryMetric name="Verified returned" value={returned} detail="Return of capital" />
    <SummaryMetric name="Remaining capital" value={remainingCapital} detail="Funded less returned" />
    <SummaryMetric name="Remaining principal" value={remainingPrincipal} detail={debtRecords.length ? "Manual debt records" : "No debt balance recorded"} />
    <SummaryMetric name="Open obligations" value={openObligationAmount} detail={openObligations.length ? "Principal, return and fees due" : "Unknown until obligations are generated"} />
    <SummaryMetric name="Next payment" value={nextValue} detail={nextDetail} />
    <SummaryMetric name="Maturity" value={maturity ? dateLabel(maturity.maturityOn) : "Unknown"} detail={maturity ? `${maturity.instrument.name}${maturity.balloonCents !== null ? ` · balloon ${money(maturity.balloonCents, maturity.instrument.currency)}` : ""}` : "No maturity date recorded"} />
  </div>;
}

function obligationExpectedLabel(obligation: InvestorDetail["obligations"][number]): string { return obligation.amountComplete ? money(obligation.totalExpectedCents, obligation.currency) : `${money(obligation.knownMinimumCents, obligation.currency)} + unknown`; }

function Overview({ detail, entities, onEdit }: { detail: InvestorDetail; entities: readonly InvestorWorkspaceEntity[]; onEdit: (kind: EditorKind) => void }) { return <div className="investors-panel"><InvestorSummary account={detail} /><div className="investors-card"><div className="investors-card-header"><h3>Ownership and instruments</h3><button className="investors-button investors-button-secondary" type="button" onClick={() => onEdit("instrument")}><Plus size={15} />Add investment</button></div><div className="investors-table-wrap"><table className="investors-table"><thead><tr><th>Name</th><th>Entity</th><th>Type</th><th>Status</th><th>Committed</th><th>Face value</th><th>Maturity</th></tr></thead><tbody>{detail.instruments.map(item => <tr key={item.id}><td><div className="investors-stack"><strong>{item.name}</strong><small>{item.propertyIds.length ? `${item.propertyIds.length} linked properties` : "No property link"}</small></div></td><td>{entities.find(entity => entity.id === item.legalEntityId)?.name ?? "Scoped entity"}</td><td>{label(item.kind)}</td><td><StatusBadge value={item.status} /></td><td className="amount">{money(item.committedCents, item.currency)}</td><td className="amount">{money(item.facePrincipalCents, item.currency)}</td><td>{dateLabel(item.maturityOn)}</td></tr>)}</tbody><tfoot><tr><th scope="row">Shown: {detail.instruments.length} instruments</th><td colSpan={3}>Totals</td><td className="amount">{moneyTotals(detail.instruments.map(item => ({ cents: item.committedCents, currency: item.currency })))}</td><td className="amount">{moneyTotals(detail.instruments.map(item => ({ cents: item.facePrincipalCents, currency: item.currency })))}</td><td /></tr></tfoot></table>{!detail.instruments.length && <div className="investors-empty">Add an ownership or loan instrument to start the investor record.</div>}</div></div></div>; }

function paymentStateTotals(payments: readonly InvestorPayment[]): string {
  const labels: readonly [InvestorPayment["status"], string][] = [["manual_recorded", "Manual"], ["qbo_posted", "Posted"], ["bank_settled", "Settled"], ["review_required", "Review"], ["reversed", "Reversed"]];
  return labels.filter(([status]) => payments.some(payment => payment.status === status)).map(([status, name]) => `${name} ${moneyTotals(payments.filter(payment => payment.status === status).map(payment => ({ cents: payment.amountCents, currency: payment.currency })))}`).join(" · ");
}

function hasCurrentQboSource(payment: InvestorPayment): boolean { return payment.postedSource?.provider === "qbo" && payment.postedSourceValidity === "current"; }
function hasVerifiedSettlement(payment: InvestorPayment): boolean { return payment.settlementSource !== null && payment.status === "bank_settled"; }
function paymentSourceDescription(payment: InvestorPayment): ReactNode {
  if (hasCurrentQboSource(payment) && payment.postedSource?.provider === "qbo") {
    const reference = payment.postedSource.reference;
    return <div className="investors-stack"><strong>QBO linked</strong><small>{reference.objectType} {reference.objectId}{reference.lineId ? ` · line ${reference.lineId}` : ""}</small></div>;
  }
  const settlementSource = payment.settlementSource;
  if (hasVerifiedSettlement(payment) && settlementSource && settlementSource.provider !== "qbo") return <div className="investors-stack"><strong>Bank settled</strong><small>{settlementSource.provider} · {settlementSource.externalTransactionId} · line {settlementSource.externalLineId}</small></div>;
  if (payment.postedSource) return <div className="investors-stack"><strong>QBO source needs review</strong><small>{payment.postedSourceValidity ?? "Current read unavailable"}</small></div>;
  if (payment.status === "qbo_posted") return <div className="investors-stack"><strong>QBO source unavailable</strong><small>Posted status has no current source link</small></div>;
  if (payment.status === "bank_settled") return <div className="investors-stack"><strong>Bank source unavailable</strong><small>Settled status has no linked settlement source</small></div>;
  return <span className="investors-muted">No source linked</span>;
}

function PaymentHistory({ detail, onEdit }: { detail: InvestorDetail; onEdit: (kind: EditorKind, payment?: InvestorPayment) => void }) {
  const payments = [...detail.payments].sort(paymentHistorySort);
  return <div className="investors-card"><div className="investors-card-header"><div><h3>Payment history</h3><p className="investors-note">Recorded activity stays separate from QBO posting. Bank settlement verification is not connected for manual entry; linked settlement evidence appears when available.</p></div><button className="investors-button investors-button-secondary" type="button" onClick={() => onEdit("payment")}><Plus size={15} />Record activity</button></div><div className="investors-table-wrap"><table className="investors-table investors-history-table"><thead><tr><th>Date</th><th>Instrument</th><th>Kind</th><th className="amount">Amount</th><th className="amount">Recorded</th><th className="amount">QBO posted</th><th className="amount">Bank settled</th><th>Source</th><th>Status</th><th /></tr></thead><tbody>{payments.map(payment => <tr key={payment.id}><td>{dateLabel(payment.paymentOn)}</td><td>{detail.instruments.find(item => String(item.id) === String(payment.instrumentId))?.name ?? "—"}</td><td>{label(payment.kind)}</td><td className="amount">{money(payment.amountCents, payment.currency)}</td><td className="amount">{payment.status === "reversed" ? "—" : money(payment.amountCents, payment.currency)}</td><td className="amount">{hasCurrentQboSource(payment) ? money(payment.amountCents, payment.currency) : "—"}</td><td className="amount">{hasVerifiedSettlement(payment) ? money(payment.amountCents, payment.currency) : "—"}</td><td>{paymentSourceDescription(payment)}</td><td><StatusBadge value={payment.status} /></td><td><div className="investors-actions">{payment.status === "manual_recorded" && <button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("payment", payment)}>Edit manual</button>}{(payment.status === "manual_recorded" || payment.status === "review_required") && <button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("qbo", payment)}>Link QBO</button>}{payment.status !== "reversed" && <button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("reverse", payment)}><RotateCcw size={13} />Reverse</button>}</div></td></tr>)}</tbody><tfoot><tr><th scope="row">Shown: {payments.length} payment records</th><td>State totals</td><td colSpan={8}>{paymentStateTotals(payments)}</td></tr></tfoot></table>{!payments.length && <div className="investors-empty"><h4>No payment history</h4><p>Recorded contributions, distributions and debt payments will appear here.</p></div>}</div></div>;
}

function ScheduledHistory({ detail }: { detail: InvestorDetail }) {
  const obligations = [...detail.obligations].sort((left, right) => left.dueOn.localeCompare(right.dueOn) || String(left.id).localeCompare(String(right.id)));
  return <div className="investors-card"><div className="investors-card-header"><div><h3>Scheduled obligations</h3><p className="investors-note">Expected amounts and evidence stages are shown independently for each due date.</p></div></div><div className="investors-table-wrap"><table className="investors-table investors-history-table"><thead><tr><th>Due</th><th>Instrument</th><th className="amount">Scheduled</th><th className="amount">Recorded</th><th className="amount">QBO posted</th><th className="amount">Bank settled</th><th className="amount">Remaining</th><th>Status</th></tr></thead><tbody>{obligations.map(obligation => <tr key={obligation.id}><td>{dateLabel(obligation.dueOn)}</td><td>{detail.instruments.find(item => String(item.id) === String(obligation.instrumentId))?.name ?? "—"}</td><td className="amount">{obligationExpectedLabel(obligation)}</td><td className="amount">{money(obligation.totalRecordedCents, obligation.currency)}</td><td className="amount">{money(obligation.totalPostedCents, obligation.currency)}</td><td className="amount">{money(obligation.totalSettledCents, obligation.currency)}</td><td className="amount">{obligation.remainingDueCents === null ? `${money(obligation.knownMinimumCents, obligation.currency)} + unknown` : money(obligation.remainingDueCents, obligation.currency)}</td><td><StatusBadge value={obligation.status} /></td></tr>)}</tbody><tfoot><tr><th scope="row">Shown: {obligations.length} obligations</th><td>Filtered totals</td><td className="amount">{moneyTotals(obligations.map(item => ({ cents: item.totalExpectedCents ?? item.knownMinimumCents, currency: item.currency })))}</td><td className="amount">{moneyTotals(obligations.map(item => ({ cents: item.totalRecordedCents, currency: item.currency })))}</td><td className="amount">{moneyTotals(obligations.map(item => ({ cents: item.totalPostedCents, currency: item.currency })))}</td><td className="amount">{moneyTotals(obligations.map(item => ({ cents: item.totalSettledCents, currency: item.currency })))}</td><td colSpan={2}>{obligations.filter(item => item.remainingDueCents === null).length ? `${obligations.filter(item => item.remainingDueCents === null).length} amount${obligations.filter(item => item.remainingDueCents === null).length === 1 ? "" : "s"} partial` : ""}</td></tr></tfoot></table>{!obligations.length && <div className="investors-empty"><h4>No scheduled obligations</h4><p>Generate obligations from an active agreement when the payment schedule is documented.</p></div>}</div></div>;
}

function Payments({ rows, unscheduled, onEdit }: { rows: readonly { obligation: InvestorDetail["obligations"][number]; payments: readonly InvestorPayment[] }[]; unscheduled: readonly InvestorPayment[]; onEdit: (kind: EditorKind, payment?: InvestorPayment) => void }) {
  return <div className="investors-panel"><div className="investors-card"><div className="investors-card-header"><h3>Expected and recorded obligations</h3><button className="investors-button investors-button-secondary" type="button" onClick={() => onEdit("payment")}><Plus size={15} />Record payment</button></div><div className="investors-table-wrap"><table className="investors-table"><thead><tr><th>Period</th><th>Due</th><th>Expected</th><th>Recorded</th><th>Posted</th><th>Settled</th><th>Status</th><th /></tr></thead><tbody>{rows.map(row => { const manual = row.payments.find(payment => payment.status === "manual_recorded"); const qboCandidate = manual ?? row.payments.find(payment => payment.status === "review_required"); return <tr key={row.obligation.id}><td>{monthLabel(row.obligation.periodMonth)}</td><td>{dateLabel(row.obligation.dueOn)}</td><td className="amount">{obligationExpectedLabel(row.obligation)}</td><td className="amount">{money(row.obligation.totalRecordedCents, row.obligation.currency)}</td><td className="amount">{money(row.obligation.totalPostedCents, row.obligation.currency)}</td><td className="amount">{money(row.obligation.totalSettledCents, row.obligation.currency)}</td><td><StatusBadge value={row.obligation.status} /></td><td>{qboCandidate && <div className="investors-actions">{manual && <button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("payment", manual)}>Edit manual</button>}<button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("qbo", qboCandidate)}>Link QBO</button></div>}</td></tr>; })}</tbody><tfoot><tr><th scope="row">Shown: {rows.length} obligations</th><td>Filtered totals</td><td className="amount">{moneyTotals(rows.map(row => ({ cents: row.obligation.totalExpectedCents ?? row.obligation.knownMinimumCents, currency: row.obligation.currency })))}</td><td className="amount">{moneyTotals(rows.map(row => ({ cents: row.obligation.totalRecordedCents, currency: row.obligation.currency })))}</td><td className="amount">{moneyTotals(rows.map(row => ({ cents: row.obligation.totalPostedCents, currency: row.obligation.currency })))}</td><td className="amount">{moneyTotals(rows.map(row => ({ cents: row.obligation.totalSettledCents, currency: row.obligation.currency })))}</td><td colSpan={2}>{rows.filter(row => !row.obligation.amountComplete).length ? `${rows.filter(row => !row.obligation.amountComplete).length} expected amount${rows.filter(row => !row.obligation.amountComplete).length === 1 ? "" : "s"} partial` : ""}</td></tr></tfoot></table>{!rows.length && <div className="investors-empty">No generated obligations in this period.</div>}</div></div>{unscheduled.length > 0 && <div className="investors-card"><div className="investors-card-header"><h3>Unscheduled activity in this period</h3><span className="investors-note">Contributions and distributions without an obligation remain visible here.</span></div><div className="investors-table-wrap"><table className="investors-table"><thead><tr><th>Date</th><th>Kind</th><th>Amount</th><th>Status</th><th /></tr></thead><tbody>{unscheduled.map(payment => <tr key={payment.id}><td>{dateLabel(payment.paymentOn)}</td><td>{label(payment.kind)}</td><td className="amount">{money(payment.amountCents, payment.currency)}</td><td><StatusBadge value={payment.status} /></td><td><div className="investors-actions">{payment.status === "manual_recorded" && <button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("payment", payment)}>Edit manual</button>}{(payment.status === "manual_recorded" || payment.status === "review_required") && <button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("qbo", payment)}>Link QBO</button>}{payment.status !== "reversed" && <button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("reverse", payment)}>Reverse</button>}</div></td></tr>)}</tbody><tfoot><tr><th scope="row">Shown: {unscheduled.length} activities</th><td>State totals</td><td className="amount" colSpan={2}>{paymentStateTotals(unscheduled)}</td><td /></tr></tfoot></table></div></div>}</div>;
}

function ContractDocuments({ organizationId, legalEntityId, documentIds, documents }: { organizationId: string; legalEntityId: string; documentIds: readonly string[]; documents?: readonly InvestorDocumentOption[] }) {
  if (!documentIds.length) return <span className="investors-muted">No linked document</span>;
  const availableDocuments = documents ?? [];
  return <div className="investors-document-links">{documentIds.map(documentId => {
    const document = availableDocuments.find(item => String(item.id) === String(documentId));
    return <a key={documentId} className="investors-document-link" href={investorDocumentDownloadHref(organizationId, String(documentId), legalEntityId)} target="_blank" rel="noreferrer"><FileText size={13} />{document?.fileName ?? `Document ${documentId}`}{document?.state && <span>{label(document.state)}</span>}</a>;
  })}</div>;
}

function Contracts({ detail, organizationId: organizationIdProp, documents: sourceDocuments, api = investorsApi, onEdit, onArchive }: { detail: InvestorDetail; organizationId?: string; documents?: readonly InvestorDocumentOption[]; api?: InvestorsApi; onEdit: (kind: EditorKind, payment?: InvestorPayment, contractId?: string) => void; onArchive: (kind: "investor.party_mapping.archive" | "investor.remittance.archive", payload: Record<string, unknown>, revision: number) => void }) {
  const organizationId = organizationIdProp ?? String(detail.organizationId);
  const [loadedDocuments, setLoadedDocuments] = useState<readonly InvestorDocumentOption[]>(sourceDocuments ?? []);
  const documents = loadedDocuments;
  useEffect(() => {
    if (sourceDocuments) { setLoadedDocuments(sourceDocuments); return; }
    let cancelled = false;
    const scopes = Array.from(new Map(detail.instruments.map(item => [String(item.legalEntityId), { legalEntityId: String(item.legalEntityId), propertyIds: item.propertyIds }])).values());
    void Promise.all(scopes.map(scope => api.listDocuments(detail.organizationId, scope.legalEntityId, scope.propertyIds).then(page => page.items).catch(() => [])))
      .then(groups => {
        if (cancelled) return;
        const byId = new Map<string, InvestorDocumentOption>();
        for (const document of groups.flat()) byId.set(String(document.id), document);
        setLoadedDocuments(Array.from(byId.values()));
      });
    return () => { cancelled = true; };
  }, [api, detail, sourceDocuments]);
  const activeMappings = detail.partyMappings.filter(item => item.archivedAt === null);
  const activeRemittances = detail.remittanceInstructions.filter(item => item.archivedAt === null);
  return <div className="investors-panel">
    <div className="investors-card"><div className="investors-card-header"><h3>Agreements</h3><button className="investors-button investors-button-secondary" type="button" onClick={() => onEdit("contract")}><Plus size={15} />Add agreement</button></div><div className="investors-table-wrap"><table className="investors-table"><thead><tr><th>Agreement</th><th>Instrument</th><th>Current version</th><th>Executed</th><th>Documents</th><th>Status</th><th /></tr></thead><tbody>{detail.contracts.map(contract => { const versions = detail.contractVersions.filter(version => String(version.contractId) === String(contract.id)); const current = versions.find(version => String(version.id) === String(contract.currentVersionId)) ?? versions.filter(version => version.status === "active").at(-1) ?? versions.at(-1); const instrument = detail.instruments.find(item => String(item.id) === String(contract.instrumentId)); return <tr key={contract.id}><td><div className="investors-stack"><strong>{contract.title}</strong><small>{label(contract.kind)} · {versions.length} version{versions.length === 1 ? "" : "s"}</small></div></td><td>{instrument?.name ?? "—"}</td><td>{current ? <div className="investors-stack"><span>v{current.versionNo} <StatusBadge value={current.status} /></span><small>Effective {dateLabel(current.effectiveFrom)}{current.effectiveTo ? ` · through ${dateLabel(current.effectiveTo)}` : ""}</small></div> : <span className="investors-muted">No version</span>}</td><td>{current?.signedOn ? <div className="investors-stack"><strong>Signed</strong><small>{dateLabel(current.signedOn)}</small></div> : <span className="investors-muted">Not signed</span>}</td><td>{current && instrument ? <ContractDocuments organizationId={organizationId} legalEntityId={String(instrument.legalEntityId)} documentIds={current.sourceDocumentIds.map(String)} documents={documents} /> : <span className="investors-muted">No linked document</span>}</td><td><StatusBadge value={contract.status} /></td><td><div className="investors-actions"><button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("version", undefined, String(contract.id))}>New version</button>{contract.status === "active" && <button type="button" className="investors-button investors-button-quiet" onClick={() => onEdit("generate", undefined, String(contract.id))}>Generate obligations</button>}</div></td></tr>; })}</tbody><tfoot><tr><th scope="row">Shown: {detail.contracts.length} agreements</th><td colSpan={6}>Current version, execution and linked source documents</td></tr></tfoot></table>{!detail.contracts.length && <div className="investors-empty"><h4>No agreements</h4><button className="investors-button investors-button-secondary" type="button" onClick={() => onEdit("contract")}>Add agreement</button></div>}</div></div>
    <div className="investors-card"><div className="investors-card-header"><h3>Payees</h3><button className="investors-button investors-button-secondary" type="button" onClick={() => onEdit("party")}><Plus size={15} />Add payee</button></div><div className="investors-table-wrap"><table className="investors-table"><thead><tr><th>Name</th><th>Party</th><th>QBO payee</th><th>Effective</th><th>Status</th><th /></tr></thead><tbody>{activeMappings.map(mapping => <tr key={mapping.id}><td><strong>{mapping.displayName}</strong></td><td>{label(mapping.partyKind)}</td><td>{mapping.providerParty.objectType} {mapping.providerParty.objectId}</td><td>{dateLabel(mapping.effectiveFrom)}{mapping.effectiveTo ? ` – ${dateLabel(mapping.effectiveTo)}` : ""}</td><td><StatusBadge value={mapping.status} /></td><td><button type="button" className="investors-button investors-button-quiet" onClick={() => onArchive("investor.party_mapping.archive", { mappingId: mapping.id }, mapping.recordRevision)}>Archive</button></td></tr>)}</tbody><tfoot><tr><th scope="row">Shown: {activeMappings.length} payees</th><td colSpan={5}>Counts only</td></tr></tfoot></table>{!activeMappings.length && <div className="investors-empty"><h4>No payees</h4></div>}</div></div>
    <div className="investors-card"><div className="investors-card-header"><h3>Remittance instructions</h3><button className="investors-button investors-button-secondary" type="button" onClick={() => onEdit("remittance")} disabled={!activeMappings.length}><Plus size={15} />Add instruction</button></div><div className="investors-table-wrap"><table className="investors-table"><thead><tr><th>Instrument</th><th>Pay to</th><th>Effective</th><th>Status</th><th /></tr></thead><tbody>{activeRemittances.map(instruction => <tr key={instruction.id}><td>{detail.instruments.find(item => String(item.id) === String(instruction.instrumentId))?.name ?? "—"}</td><td>{detail.partyMappings.find(item => String(item.id) === String(instruction.partyMappingId))?.displayName ?? "—"}</td><td>{dateLabel(instruction.effectiveFrom)}{instruction.effectiveTo ? ` – ${dateLabel(instruction.effectiveTo)}` : ""}</td><td><StatusBadge value={instruction.status} /></td><td><button type="button" className="investors-button investors-button-quiet" onClick={() => onArchive("investor.remittance.archive", { instructionId: instruction.id }, instruction.recordRevision)}>Archive</button></td></tr>)}</tbody><tfoot><tr><th scope="row">Shown: {activeRemittances.length} instructions</th><td colSpan={4}>Counts only</td></tr></tfoot></table>{!activeRemittances.length && <div className="investors-empty"><h4>No remittance instructions</h4></div>}</div></div>
  </div>;
}

function Debt({ detail, onEdit }: { detail: InvestorDetail; onEdit: (kind: EditorKind) => void }) { return <div className="investors-panel"><div className="investors-card"><div className="investors-card-header"><h3>Debt terms and balance</h3><button className="investors-button investors-button-secondary" type="button" onClick={() => onEdit("debt")}><Plus size={15} />Add debt</button></div><div className="investors-table-wrap"><table className="investors-table"><thead><tr><th>Instrument</th><th>Original</th><th>Funded</th><th>Outstanding</th><th>Rate</th><th>Schedule</th></tr></thead><tbody>{detail.debt.map(debt => <tr key={debt.id}><td>{detail.instruments.find(item => String(item.id) === String(debt.instrumentId))?.name ?? "—"}</td><td className="amount">{money(debt.originalPrincipalCents, debt.currency)}</td><td className="amount">{money(debt.fundedCapitalCents, debt.currency)}</td><td className="amount">{money(debt.outstandingPrincipalCents, debt.currency)}</td><td>{debt.annualRate}</td><td>{label(debt.schedule)} · {label(debt.dayCount)}</td></tr>)}</tbody><tfoot><tr><th scope="row">Shown: {detail.debt.length} debt records</th><td className="amount">{moneyTotals(detail.debt.map(debt => ({ cents: debt.originalPrincipalCents, currency: debt.currency })))}</td><td className="amount">{moneyTotals(detail.debt.map(debt => ({ cents: debt.fundedCapitalCents, currency: debt.currency })))}</td><td className="amount">{moneyTotals(detail.debt.map(debt => ({ cents: debt.outstandingPrincipalCents, currency: debt.currency })))}</td><td colSpan={2}>Filtered totals</td></tr></tfoot></table>{!detail.debt.length && <div className="investors-empty">No debt schedule has been entered.</div>}</div></div></div>; }

function Activity({ detail, onEdit }: { detail: InvestorDetail; onEdit: (kind: EditorKind, payment?: InvestorPayment) => void }) { return <div className="investors-panel"><PaymentHistory detail={detail} onEdit={onEdit} /><ScheduledHistory detail={detail} /></div>; }

export function InvestorWorkspace({ organizationId, organizationName, entities = [], api = investorsApi, initialAccountId, activeTab = "overview", onTabChange, onNavigate }: InvestorWorkspaceProps) {
  const [list, setList] = useState<readonly InvestorAccount[]>([]); const [selectedId, setSelectedId] = useState(initialAccountId); const [detail, setDetail] = useState<InvestorDetail>(); const [search, setSearch] = useState(""); const [loading, setLoading] = useState(true); const [detailLoading, setDetailLoading] = useState(false); const [error, setError] = useState<unknown>(); const [editor, setEditor] = useState<EditorState>(null); const [editorError, setEditorError] = useState<unknown>(); const [saving, setSaving] = useState(false); const [contacts, setContacts] = useState<readonly { id: string; displayName: string; kind: string }[]>([]); const [documents, setDocuments] = useState<readonly InvestorDocumentOption[]>([]); const [monthlyRows, setMonthlyRows] = useState<readonly { obligation: InvestorDetail["obligations"][number]; payments: readonly InvestorPayment[] }[]>([]); const [monthlyUnscheduled, setMonthlyUnscheduled] = useState<readonly InvestorPayment[]>([]); const [financialSources, setFinancialSources] = useState<readonly FinancialSourceLineResolution[]>([]); const [financialSourcesLoading, setFinancialSourcesLoading] = useState(false); const [realms, setRealms] = useState<readonly { legalEntityId: string; environment: string; realmId: string }[]>([]);
  const selectedTab = activeTab ?? "overview";
  // Only the latest list and detail reads may land: a slower earlier response
  // (a previous search or a previously selected account) is discarded.
  const listRequest = useRef(0);
  const detailRequest = useRef(0);
  const [monthlyError, setMonthlyError] = useState<unknown>();
  const monthlyAccount = useRef<string>();
  const reloadList = useCallback(async () => { const request = ++listRequest.current; setLoading(true); try { const response = await api.listInvestors(organizationId, { search }); if (request !== listRequest.current) return; setList(response.items); setSelectedId(current => current && response.items.some(item => String(item.id) === current) ? current : response.items[0] ? String(response.items[0].id) : undefined); setError(undefined); } catch (nextError) { if (request === listRequest.current) setError(nextError); } finally { if (request === listRequest.current) setLoading(false); } }, [api, organizationId, search]);
  const reloadDetail = useCallback(async () => { const request = ++detailRequest.current; if (!selectedId) { setDetail(undefined); setDetailLoading(false); return; } setDetail(current => current && String(current.id) === selectedId ? current : undefined); setDetailLoading(true); try { const response = await api.getInvestor(organizationId, selectedId); if (request !== detailRequest.current) return; setDetail(response); setError(undefined); } catch (nextError) { if (request === detailRequest.current) setError(nextError); } finally { if (request === detailRequest.current) setDetailLoading(false); } }, [api, organizationId, selectedId]);
  useEffect(() => { void reloadList(); }, [reloadList]);
  useEffect(() => { void reloadDetail(); }, [reloadDetail]);
  useEffect(() => { if (!editor || editor.kind !== "account") return; void api.listContacts(organizationId).then(response => setContacts(response.items)).catch(() => setContacts([])); }, [api, editor, organizationId]);
  useEffect(() => {
    if (!editor || !detail || !["contract", "version", "party", "remittance"].includes(editor.kind)) { setDocuments([]); return; }
    const instrumentId = editor.instrumentId ?? String(detail.instruments[0]?.id ?? "");
    const item = detail.instruments.find(candidate => String(candidate.id) === instrumentId);
    if (!item) { setDocuments([]); return; }
    const propertyIds = editor.kind === "contract" || editor.kind === "version" ? item.propertyIds : Array.from(new Set(detail.instruments.filter(candidate => candidate.legalEntityId === item.legalEntityId).flatMap(candidate => candidate.propertyIds)));
    setDocuments([]);
    void api.listDocuments(organizationId, item.legalEntityId, propertyIds).then(response => setDocuments(response.items)).catch(() => setDocuments([]));
  }, [api, detail, editor?.instrumentId, editor?.kind, organizationId]);
  useEffect(() => {
    if (!editor || editor.kind !== "party" || !detail) { setRealms([]); return; }
    let cancelled = false;
    const entityIds = Array.from(new Set(detail.instruments.map(item => String(item.legalEntityId))));
    void Promise.all(entityIds.map(legalEntityId => api.listFinancialSources(organizationId, legalEntityId).then(page => page.items.map(item => ({ legalEntityId, environment: item.source.environment, realmId: item.source.realmId }))).catch(() => [])))
      .then(groups => { if (cancelled) return; const seen = new Map<string, { legalEntityId: string; environment: string; realmId: string }>(); for (const item of groups.flat()) seen.set(`${item.legalEntityId}|${item.environment}|${item.realmId}`, item); setRealms(Array.from(seen.values())); });
    return () => { cancelled = true; };
  }, [api, detail, editor?.kind, organizationId]);
  useEffect(() => {
    if (!editor || editor.kind !== "qbo" || !editor.payment) { setFinancialSources([]); setFinancialSourcesLoading(false); return; }
    const payment = editor.payment;
    const through = payment.paymentOn;
    const from = shiftMonth(`${through.slice(0, 7)}-01`, -1);
    setFinancialSourcesLoading(true);
    let cancelled = false;
    void (async () => {
      try {
        const items: FinancialSourceLineResolution[] = [];
        let cursor: string | undefined;
        do {
          const page = await api.listFinancialSources(organizationId, payment.legalEntityId, from, through, cursor);
          items.push(...page.items);
          cursor = page.nextCursor ?? undefined;
        } while (cursor && !cancelled);
        if (!cancelled) setFinancialSources(items);
      } catch {
        if (!cancelled) setFinancialSources([]);
      } finally {
        if (!cancelled) setFinancialSourcesLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [api, editor, organizationId]);
  useEffect(() => {
    if (selectedTab !== "payments" || !detail) return;
    const entity = detail.instruments[0]?.legalEntityId;
    if (!entity) { setMonthlyRows([]); setMonthlyUnscheduled([]); return; }
    const through = monthFor();
    const from = shiftMonth(through, -6);
    let cancelled = false;
    if (monthlyAccount.current !== String(detail.id)) { monthlyAccount.current = String(detail.id); setMonthlyRows([]); setMonthlyUnscheduled([]); }
    setMonthlyError(undefined);
    void (async () => {
      try {
        const rows: { obligation: InvestorDetail["obligations"][number]; payments: readonly InvestorPayment[] }[] = [];
        let unscheduled: readonly InvestorPayment[] = [];
        let cursor: string | undefined;
        do {
          const page = await api.listMonthlyPayments(organizationId, { accountId: detail.id, legalEntityId: entity, fromMonth: isoDateSchema.parse(from), throughMonth: isoDateSchema.parse(through), limit: 100, cursor });
          rows.push(...page.items);
          if (!cursor) unscheduled = page.unscheduledPayments;
          cursor = page.nextCursor ?? undefined;
        } while (cursor && !cancelled);
        if (!cancelled) { setMonthlyRows(rows); setMonthlyUnscheduled(unscheduled); }
      } catch (nextError) {
        if (!cancelled) { setMonthlyRows([]); setMonthlyUnscheduled([]); setMonthlyError(nextError); }
      }
    })();
    return () => { cancelled = true; };
  }, [api, detail, organizationId, selectedTab]);
  const choose = (id: string) => { setSelectedId(id); onNavigate?.(id); };
  const selectedAccount = useMemo(() => list.find(item => String(item.id) === selectedId), [list, selectedId]);
  const scopeFor = (currentDetail = detail, payload: Record<string, unknown> = {}): CompanyScope => {
    const directEntity = typeof payload.legalEntityId === "string" && payload.legalEntityId.length ? payload.legalEntityId : undefined;
    const payloadInstrumentId = typeof payload.instrumentId === "string" ? payload.instrumentId : undefined;
    const payloadPaymentId = typeof payload.paymentId === "string" ? payload.paymentId : undefined;
    const payloadObligationId = typeof payload.obligationId === "string" ? payload.obligationId : undefined;
    const instrument = payloadInstrumentId ? currentDetail?.instruments.find(item => String(item.id) === payloadInstrumentId) : undefined;
    const payment = payloadPaymentId ? currentDetail?.payments.find(item => String(item.id) === payloadPaymentId) : undefined;
    const obligation = payloadObligationId ? currentDetail?.obligations.find(item => String(item.id) === payloadObligationId) : undefined;
    const obligationInstrument = obligation ? currentDetail?.instruments.find(item => String(item.id) === String(obligation.instrumentId)) : undefined;
    const providerParty = typeof payload.providerParty === "object" && payload.providerParty !== null ? payload.providerParty as { legalEntityId?: unknown } : undefined;
    const providerEntity = typeof providerParty?.legalEntityId === "string" ? providerParty.legalEntityId : undefined;
    return companyScopeSchema.parse({ organizationId, legalEntityId: directEntity ?? providerEntity ?? instrument?.legalEntityId ?? payment?.legalEntityId ?? obligationInstrument?.legalEntityId });
  };
  const closeEditor = () => { if (!saving) { setEditor(null); setEditorError(undefined); } };
  const saveCommand = async (kind: string, payload: Record<string, unknown>, expectedRevision?: number, scope?: CompanyScope) => { const validationMessage = payload.__validationError; if (typeof validationMessage === "string") { setEditorError(new Error(validationMessage)); return; } setSaving(true); setEditorError(undefined); try { await api.sendCommand(organizationId, kind as never, createInvestorCommandEnvelope(scope ?? scopeFor(detail, payload), payload, expectedRevision)); setEditor(null); await reloadList(); await reloadDetail(); } catch (nextError) { setEditorError(nextError); } finally { setSaving(false); } };
  const onEdit = (kind: EditorKind, payment?: InvestorPayment, contractId?: string) => { const contract = contractId ? detail?.contracts.find(item => String(item.id) === contractId) : undefined; setEditor({ kind, payment, contractId, instrumentId: contract ? String(contract.instrumentId) : kind === "contract" ? String(detail?.instruments[0]?.id ?? "") : undefined }); setEditorError(undefined); };
  const archiveRelation = (kind: "investor.party_mapping.archive" | "investor.remittance.archive", payload: Record<string, unknown>, revision: number) => { if (typeof window !== "undefined" && !window.confirm("Archive this record?")) return; void saveCommand(kind, payload, revision, scopeFor(detail, { legalEntityId: kind === "investor.party_mapping.archive" ? detail?.partyMappings.find(item => String(item.id) === payload.mappingId)?.legalEntityId : detail?.remittanceInstructions.find(item => String(item.id) === payload.instructionId)?.legalEntityId })); };
  const editorContract = editor?.contractId ? detail?.contracts.find(item => String(item.id) === editor.contractId) : undefined;
  const searchActive = search.trim().length > 0;
  // First load shows one loading line; a search keeps the list pane (and its input) mounted.
  if (loading && !list.length && !searchActive) return <div className="investors-workspace"><Loading /></div>;
  // No accounts and nothing searched: one empty state with the only create action on the page.
  const noAccountsYet = !loading && !error && list.length === 0 && !searchActive;
  const openNewInvestor = () => { setContacts([]); setEditor({ kind: "account" }); };
  return <div className="investors-workspace"><div className="investors-toolbar"><div><h1>Investors</h1>{organizationName && <p>{organizationName}</p>}</div><div className="investors-toolbar-actions"><button type="button" className="investors-button investors-button-secondary" onClick={() => void reloadList()}><RefreshCw size={14} />Refresh</button>{!noAccountsYet && <button type="button" className="investors-button investors-button-primary" onClick={openNewInvestor}><Plus size={15} />New investor</button>}</div></div><ErrorMessage error={error} onRetry={() => { void reloadList(); void reloadDetail(); }} />{noAccountsYet ? <div className="investors-empty-page"><EmptyState icon={<WalletCards size={28} />} title="No investor accounts yet" action={<button type="button" className="investors-button investors-button-primary" onClick={openNewInvestor}><Plus size={15} />New investor</button>}>Add each investor or lender with their agreement terms. Payment calendars, maturities and dashboard obligations come from these accounts.</EmptyState></div> : <div className="investors-layout"><aside className="investors-list-pane"><div className="investors-filter"><label htmlFor="investor-search" className="investors-search"><Search size={14} aria-hidden="true" /><span className="sr-only">Search</span><input id="investor-search" value={search} onChange={event => setSearch(event.currentTarget.value)} placeholder="Name or account" /></label><select aria-label="Investor status" defaultValue="active"><option value="active">Active accounts</option><option value="archived">Archived accounts</option></select></div><div className="investors-list">{list.map(account => <button type="button" className={`investors-list-row ${String(account.id) === selectedId ? "is-selected" : ""}`} key={account.id} onClick={() => choose(String(account.id))}><strong>{account.displayName}</strong><div className="investors-list-meta"><small>{account.rollups.length ? `${account.rollups.length} currency rollup${account.rollups.length === 1 ? "" : "s"}` : "No instruments yet"}</small><StatusBadge value={account.status} /></div></button>)}{!list.length && searchActive && (loading ? <Loading text="Searching…" /> : <div className="investors-empty">No investor accounts match this search.</div>)}</div><div className="investors-list-summary" aria-label="Investor account totals">Shown: {list.length} investor account{list.length === 1 ? "" : "s"} · {list.filter(account => account.status === "active").length} active · {list.filter(account => account.status === "archived").length} archived</div></aside><main className="investors-main">{detailLoading && !detail ? <Loading /> : !detail ? (list.length ? <div className="investors-empty"><WalletCards size={25} /><strong>Select an investor account</strong><span>Choose an account from the list to review its terms, payments and activity.</span></div> : null) : <><header className="investors-detail-head"><div><span className="investors-eyebrow">Investor account</span><h2>{detail.displayName}</h2><p><StatusBadge value={detail.status} /> <span>Linked company contact</span></p></div><div className="investors-actions"><button type="button" className="investors-button investors-button-secondary" onClick={() => setEditor({ kind: "instrument" })}><Plus size={15} />Add investment</button></div></header><nav className="investors-tabs" aria-label="Investor account sections">{INVESTOR_TABS.map(tab => <button type="button" key={tab} className={selectedTab === tab ? "is-active" : ""} aria-current={selectedTab === tab ? "page" : undefined} onClick={() => onTabChange?.(tab)}>{tabLabels[tab]}</button>)}</nav>{selectedTab === "overview" && <Overview detail={detail} entities={entities} onEdit={onEdit} />}{selectedTab === "payments" && <div className="investors-panel"><PaymentCalendarPanel api={api} organizationId={organizationId} detail={detail} month={monthFor()} /><ErrorMessage error={monthlyError} /><Payments rows={monthlyRows} unscheduled={monthlyUnscheduled} onEdit={onEdit} /></div>}{selectedTab === "capital" && <CapitalPanel detail={detail} />}{selectedTab === "contracts" && <Contracts detail={detail} onEdit={onEdit} onArchive={archiveRelation} />}{selectedTab === "debt" && <div className="investors-panel"><DebtMaturitiesPanel key={String(detail.id)} api={api} organizationId={organizationId} detail={detail} /><Debt detail={detail} onEdit={onEdit} /></div>}{selectedTab === "activity" && <Activity detail={detail} onEdit={onEdit} />}</>}</main></div>}{editor?.kind === "account" && <AccountEditor contacts={contacts} onSave={payload => void saveCommand("investor.account.create", payload, undefined, companyScopeSchema.parse({ organizationId }))} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "instrument" && detail && <InstrumentEditor detail={detail} entities={entities} onSave={payload => void saveCommand("investor.instrument.create", payload)} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "contract" && detail && <ContractEditor detail={detail} instrumentId={editor.instrumentId ?? String(detail.instruments[0]?.id ?? "")} documents={documents} onInstrumentChange={instrumentId => setEditor(current => current?.kind === "contract" ? { ...current, instrumentId } : current)} onSave={payload => void saveCommand("investor.contract.create", payload)} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "version" && detail && editorContract && <ContractEditor detail={detail} contract={editorContract} instrumentId={String(editorContract.instrumentId)} documents={documents} onInstrumentChange={() => undefined} onSave={payload => void saveCommand("investor.contract.version.create", payload, editorContract.recordRevision, scopeFor(detail, { instrumentId: String(editorContract.instrumentId) }))} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "generate" && detail && editor.contractId && <GenerateEditor detail={detail} contractId={editor.contractId} onSave={payload => void saveCommand("investor.obligation.generate", payload)} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "party" && detail && <PartyEditor detail={detail} realms={realms} documents={documents} onSave={payload => void saveCommand("investor.party_mapping.create", payload)} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "remittance" && detail && <RemittanceEditor detail={detail} documents={documents} onSave={payload => void saveCommand("investor.remittance.create", payload)} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "debt" && detail && <DebtEditor detail={detail} onSave={payload => void saveCommand("investor.debt.create", payload)} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "payment" && detail && <PaymentEditor key={editor.payment?.id ?? "new"} detail={detail} payment={editor.payment} onSave={payload => void saveCommand(editor.payment ? "investor.payment.edit_manual" : "investor.payment.record", payload, editor.payment?.recordRevision)} onClose={closeEditor} saving={saving} error={editorError} />} {editor?.kind === "reverse" && editor.payment && <ReverseEditor payment={editor.payment} onSave={payload => void saveCommand("investor.payment.reverse", payload, editor.payment!.recordRevision)} onClose={closeEditor} saving={saving} error={editorError} />}{editor?.kind === "qbo" && detail && editor.payment && <SourceEditor payment={editor.payment} sources={financialSources} sourcesLoading={financialSourcesLoading} onSave={payload => void saveCommand("investor.payment.link_qbo", payload, editor.payment!.recordRevision)} onClose={closeEditor} saving={saving} error={editorError} />}</div>;
}

export default InvestorWorkspace;
